INSERT INTO public.agent_profiles VALUES ('seo-agent', NULL, 'SEO-Analyse (lokal)', 'Prüft Websites auf SEO, komplett lokal auf diesem PC. Öffnet Links im Browser, macht Screenshots, führt ein vollständiges Audit durch (Crawl, 52 Regeln, Bewertung mit Laya) und schreibt einen Markdown-Bericht mit Maßnahmen-Tabelle. Beispiel: "Mach SEO für https://example.de".', 'seo-agent', 'public', NULL, '2026-10-04 11:54:45.096224+00', '2026-10-17 09:10:10.575+00', NULL, NULL);
