INSERT INTO public.channel_memberships VALUES ('channel_0882be8d-d55b-4db6-853a-2ced31b0b701', 'Xx3DRBa5O38j5I50bcmQxbhvDyHziizu', '2026-10-05 20:11:06.679954+00', NULL, '2026-10-05 20:14:26.733268+00');
INSERT INTO public.components VALUES ('askApproval', 'Approval', 'decision', 'Ask the person to approve or decline something, and WAIT for their answer. Use before doing anything you cannot undo, spending money, sending a message, changing a record. You are given their decision and any reason they typed.', 'Ask the person to approve or decline something, and WAIT for their answer. Use before doing anything you cannot undo, spending money, sending a message, changing a record. You are given their decision and any reason they typed.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('askChoice', 'Choice', 'decision', 'Ask the person to pick one of several options, and WAIT for their answer. Use when you cannot sensibly guess which one they meant. You are given the id of the option they chose.', 'Ask the person to pick one of several options, and WAIT for their answer. Use when you cannot sensibly guess which one they meant. You are given the id of the option they chose.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('askForm', 'Form', 'decision', 'Ask the person to fill in a short form and WAIT for their answers. Use when several related details are needed together. Provide up to eight labeled text, email, number, select, or textarea fields with unique IDs. Mark required fields and give options for selects. Never request passwords or secrets. The result has status submitted and values keyed by field ID; numbers are returned as numbers and blank optional fields are omitted.', 'Ask the person to fill in a short form and WAIT for their answers. Use when several related details are needed together. Provide up to eight labeled text, email, number, select, or textarea fields with unique IDs. Mark required fields and give options for selects. Never request passwords or secrets. The result has status submitted and values keyed by field ID; numbers are returned as numbers and blank optional fields are omitted.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showActivityReport', 'Activity report', 'card', 'Show what this deployment has actually been doing, read from its own records rather than from anything you know. Use for ''what have the Bots been up to'' and ''what has been refused''. You choose the report and the period; the figures are read for you and you will not see them.', 'Show what this deployment has actually been doing, read from its own records rather than from anything you know. Use for ''what have the Bots been up to'' and ''what has been refused''. You choose the report and the period; the figures are read for you and you will not see them.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showAreaChart', 'Area chart', 'chart', 'The same as showLineChart with the area under each line filled. Use for volume or accumulation rather than for a rate.', 'The same as showLineChart with the area under each line filled. Use for volume or accumulation rather than for a rate.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showBarChart', 'Bar chart', 'chart', 'Show values as a bar chart. Use when comparing a handful of named things, teams, months, categories. Not for a trend over time, which is showLineChart.', 'Show values as a bar chart. Use when comparing a handful of named things, teams, months, categories. Not for a trend over time, which is showLineChart.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showChecklist', 'Checklist', 'card', 'Show a list of things and which are done. Reporting only, the person cannot tick these, so do not use it to ask for anything.', 'Show a list of things and which are done. Reporting only, the person cannot tick these, so do not use it to ask for anything.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showLineChart', 'Line chart', 'chart', 'Show one or more series over an ordered axis, usually time. Every series must have one value per label.', 'Show one or more series over an ordered axis, usually time. Every series must have one value per label.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showMetrics', 'Headline figures', 'card', 'Show up to six headline figures, each with an optional movement. Use for a summary somebody reads at a glance.', 'Show up to six headline figures, each with an optional movement. Use for a summary somebody reads at a glance.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showNotice', 'Notice', 'card', 'Show a headline, a short explanation and optional supporting points. Use instead of writing several paragraphs of prose.', 'Show a headline, a short explanation and optional supporting points. Use instead of writing several paragraphs of prose.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showPieChart', 'Donut chart', 'chart', 'Show how a whole is divided, as a donut with a legend. Use only when the parts sum to something meaningful, and prefer a bar chart above about six slices.', 'Show how a whole is divided, as a donut with a legend. Use only when the parts sum to something meaningful, and prefer a bar chart above about six slices.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showProgress', 'Progress against target', 'chart', 'Show values against their targets as progress bars. Use for ''are we there yet'' questions, budget spent against budget, done against planned.', 'Show values against their targets as progress bars. Use for ''are we there yet'' questions, budget spent against budget, done against planned.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showQuote', 'Quotation', 'card', 'Show a quotation with its attribution. Use when the exact words matter, something a person said, or a line from a document you were given.', 'Show a quotation with its attribution. Use when the exact words matter, something a person said, or a line from a document you were given.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showRecord', 'Record', 'card', 'Show one thing and its fields, an order, a person, a ticket. Use instead of describing a record in prose.', 'Show one thing and its fields, an order, a person, a ticket. Use instead of describing a record in prose.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
INSERT INTO public.components VALUES ('showTable', 'Data table', 'card', 'Show a sortable table to compare records, plans, or other structured facts. Supply up to eight columns and 100 rows, with exactly one cell per column. Use numbers for quantities so sorting is numeric. Show only data you have; do not invent rows.', 'Show a sortable table to compare records, plans, or other structured facts. Supply up to eight columns and 100 rows, with exactly one cell per column. Use numbers for quantities so sorting is numeric. Show only data you have; do not invent rows.', true, '2026-10-01 17:44:09.102+00', 'the build', '2026-10-01 17:44:09.105599+00', '2026-10-01 17:44:09.105599+00');
