INSERT INTO public.connect_mcp_servers VALUES ('browser-seo-agent', '{"id": "browser-seo-agent", "bin": "cli.js", "pkg": "@playwright/mcp", "args": ["--browser", "chrome", "--executable-path", "C:\\Users\\Kunc GmbH\\AppData\\Local\\imput\\Helium\\Application\\chrome.exe", "--user-data-dir", "C:\\Users\\Kunc GmbH\\AppData\\Local\\ConnectAgents\\seo-agent\\helium", "--output-dir", "C:\\Users\\Kunc GmbH\\AppData\\Local\\ConnectAgents\\seo-agent\\output", "--image-responses", "omit", "--headless"], "title": "Mein Browser", "options": {"profile": "C:\\Users\\Kunc GmbH\\AppData\\Local\\ConnectAgents\\seo-agent\\helium", "headless": true}, "secrets": [], "createdAt": "2026-10-04T12:26:47.062Z", "transport": "stdio", "catalogKey": "browser", "ownerAgentId": "seo-agent"}', '[{"name": "browser_close", "description": "Close the page", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {}, "additionalProperties": false}}, {"name": "browser_resize", "description": "Resize the browser window", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["width", "height"], "properties": {"width": {"type": "number", "description": "Width of the browser window"}, "height": {"type": "number", "description": "Height of the browser window"}}, "additionalProperties": false}}, {"name": "browser_console_messages", "description": "Returns all console messages", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["level"], "properties": {"all": {"type": "boolean", "description": "Return all console messages since the beginning of the session, not just since the last navigation. Defaults to false."}, "level": {"enum": ["error", "warning", "info", "debug"], "type": "string", "default": "info", "description": "Level of the console messages to return. Each level includes the messages of more severe levels. Defaults to \"info\"."}, "filename": {"type": "string", "description": "File name to save the console messages to. Relative file names are resolved against the workspace root. If not provided, messages are returned as text."}}, "additionalProperties": false}}, {"name": "browser_handle_dialog", "description": "Handle a dialog", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["accept"], "properties": {"accept": {"type": "boolean", "description": "Whether to accept the dialog."}, "promptText": {"type": "string", "description": "The text of the prompt in case of a prompt dialog."}}, "additionalProperties": false}}, {"name": "browser_emulate_media", "description": "Emulate CSS media features for the page, for example switch between the light and dark color scheme. Omitted parameters are left unchanged; null clears an override.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"media": {"anyOf": [{"enum": ["screen", "print"], "type": "string"}, {"type": "null"}], "description": "Changes the CSS media type of the page"}, "contrast": {"anyOf": [{"enum": ["more", "no-preference"], "type": "string"}, {"type": "null"}], "description": "Emulates the prefers-contrast media feature"}, "colorScheme": {"anyOf": [{"enum": ["light", "dark"], "type": "string"}, {"type": "null"}], "description": "Emulates the prefers-color-scheme media feature"}, "forcedColors": {"anyOf": [{"enum": ["active", "none"], "type": "string"}, {"type": "null"}], "description": "Emulates the forced-colors media feature"}, "reducedMotion": {"anyOf": [{"enum": ["reduce", "no-preference"], "type": "string"}, {"type": "null"}], "description": "Emulates the prefers-reduced-motion media feature"}}, "additionalProperties": false}}, {"name": "browser_evaluate", "description": "Evaluate JavaScript expression on page or element", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["function"], "properties": {"target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}, "filename": {"type": "string", "description": "File name to save the result to. Relative file names are resolved against the workspace root. If not provided, result is returned as text."}, "function": {"type": "string", "description": "() => { /* code */ } or (element) => { /* code */ } when element is provided"}}, "additionalProperties": false}}, {"name": "browser_file_upload", "description": "Upload one or multiple files", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"paths": {"type": "array", "items": {"type": "string"}, "description": "The absolute paths to the files to upload. Can be single file or multiple files. If omitted, file chooser is cancelled."}}, "additionalProperties": false}}, {"name": "browser_drop", "description": "Drop files or MIME-typed data onto an element, as if dragged from outside the page. At least one of \"paths\" or \"data\" must be provided.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["target"], "properties": {"data": {"type": "object", "description": "Data to drop, as a map of MIME type to string value (e.g. {\"text/plain\": \"hello\", \"text/uri-list\": \"https://example.com\"}).", "propertyNames": {"type": "string"}, "additionalProperties": {"type": "string"}}, "paths": {"type": "array", "items": {"type": "string"}, "description": "Absolute paths to files to drop onto the element."}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}}, {"name": "browser_find", "description": "Search the accessibility snapshot of the current page for text or a regular expression. Returns matching snapshot nodes with a few lines of surrounding context (like search snippets), each shown under its path from the root of the tree, which is cheaper than capturing the whole snapshot when you only need to locate an element and its ref.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"text": {"type": "string", "description": "Plain text to search for in the page snapshot (case-insensitive substring match). Provide either text or regex, not both."}, "regex": {"type": "string", "description": "Regular expression to search for in the page snapshot. Matching is case-sensitive by default; wrap the pattern in slashes to add flags, e.g. \"/error/i\" for case-insensitive. Provide either text or regex, not both."}, "filename": {"type": "string", "description": "Save results to a file instead of returning them in the response. Relative file names are resolved against the workspace root."}}, "additionalProperties": false}}, {"name": "browser_fill_form", "description": "Fill multiple form fields", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["fields"], "properties": {"fields": {"type": "array", "items": {"type": "object", "required": ["target", "name", "type", "value"], "properties": {"name": {"type": "string", "description": "Human-readable field name"}, "type": {"enum": ["textbox", "checkbox", "radio", "combobox", "slider"], "type": "string", "description": "Type of the field"}, "value": {"type": "string", "description": "Value to fill in the field. If the field is a checkbox, the value should be `true` or `false`. If the field is a combobox, the value should be the text of the option."}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}, "description": "Fields to fill in"}}, "additionalProperties": false}}, {"name": "browser_press_key", "description": "Press a key on the keyboard", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["key"], "properties": {"key": {"type": "string", "description": "Name of the key to press or a character to generate, such as `ArrowLeft` or `a`"}}, "additionalProperties": false}}, {"name": "browser_type", "description": "Type text into editable element", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["target", "text"], "properties": {"text": {"type": "string", "description": "Text to type into the element"}, "slowly": {"type": "boolean", "description": "Whether to type one character at a time. Useful for triggering key handlers in the page. By default entire text is filled in at once."}, "submit": {"type": "boolean", "description": "Whether to submit entered text (press Enter after)"}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}}, {"name": "browser_navigate", "description": "Navigate to a URL", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["url"], "properties": {"url": {"type": "string", "description": "The URL to navigate to"}}, "additionalProperties": false}}, {"name": "browser_navigate_back", "description": "Go back to the previous page in the history", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {}, "additionalProperties": false}}, {"name": "browser_network_requests", "description": "Returns a numbered list of network requests since loading the page. Use browser_network_request with the number to get full details.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["static"], "properties": {"filter": {"type": "string", "description": "Only return requests whose URL matches this regexp (e.g. \"/api/.*user\")."}, "static": {"type": "boolean", "default": false, "description": "Whether to include successful static resources like images, fonts, scripts, etc. Defaults to false."}, "filename": {"type": "string", "description": "File name to save the network requests to. Relative file names are resolved against the workspace root. If not provided, requests are returned as text."}}, "additionalProperties": false}}, {"name": "browser_network_request", "description": "Returns full details (headers and body) of a single network request, or a single part if `part` is set. Use the number from browser_network_requests.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["index"], "properties": {"part": {"enum": ["request-headers", "request-body", "response-headers", "response-body"], "type": "string", "description": "Return only this part of the request. Omit to return full details."}, "index": {"type": "integer", "maximum": 9007199254740991, "minimum": 1, "description": "1-based index of the request, as printed by browser_network_requests."}, "filename": {"type": "string", "description": "File name to save the result to. Relative file names are resolved against the workspace root. If not provided, output is returned as text."}}, "additionalProperties": false}}, {"name": "browser_run_code_unsafe", "description": "Run a Playwright code snippet. Unsafe: executes arbitrary JavaScript in the Playwright server process and is RCE-equivalent.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"code": {"type": "string", "description": "A JavaScript function containing Playwright code to execute. It will be invoked with a single argument, page, which you can use for any page interaction. For example: `async (page) => { await page.getByRole(''button'', { name: ''Submit'' }).click(); return await page.title(); }`"}, "filename": {"type": "string", "description": "Load code from the specified file. Relative file names are resolved against the workspace root. If both code and filename are provided, code will be ignored."}}, "additionalProperties": false}}, {"name": "browser_take_screenshot", "description": "Take a screenshot of the current page. You can''t perform actions based on the screenshot, use browser_snapshot for actions.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["scale"], "properties": {"type": {"enum": ["png", "jpeg", "webp"], "type": "string", "description": "Image format for the screenshot. If unset, inferred from the filename extension, otherwise png."}, "scale": {"enum": ["css", "device"], "type": "string", "default": "css", "description": "Image resolution scale. \"css\" produces a screenshot sized in CSS pixels (smaller, consistent across devices). \"device\" produces a high-resolution screenshot using device pixels (larger, accounts for the device pixel ratio). Default is css."}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}, "filename": {"type": "string", "description": "File name to save the screenshot to. Relative file names are resolved against the workspace root. If not specified, the screenshot is saved into the output directory as `page-{timestamp}.{png|jpeg|webp}`."}, "fullPage": {"type": "boolean", "description": "When true, takes a screenshot of the full scrollable page, instead of the currently visible viewport. Cannot be used with element screenshots."}}, "additionalProperties": false}}, {"name": "browser_snapshot", "description": "Capture accessibility snapshot of the current page, this is better than screenshot", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"boxes": {"type": "boolean", "description": "Include each element''s bounding box as [box=x,y,width,height] in the snapshot. Coordinates are viewport-relative, in CSS pixels (Element.getBoundingClientRect)"}, "depth": {"type": "number", "description": "Limit the depth of the snapshot tree"}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "filename": {"type": "string", "description": "Save snapshot to a file instead of returning it in the response. Relative file names are resolved against the workspace root."}}, "additionalProperties": false}}, {"name": "browser_click", "description": "Perform click on a web page", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["target"], "properties": {"button": {"enum": ["left", "right", "middle"], "type": "string", "description": "Button to click, defaults to left"}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}, "modifiers": {"type": "array", "items": {"enum": ["Alt", "Control", "ControlOrMeta", "Meta", "Shift"], "type": "string"}, "description": "Modifier keys to press"}, "doubleClick": {"type": "boolean", "description": "Whether to perform a double click instead of a single click"}}, "additionalProperties": false}}, {"name": "browser_drag", "description": "Perform drag and drop between two elements", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["startTarget", "endTarget"], "properties": {"endTarget": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "endElement": {"type": "string", "description": "Human-readable target element description used to obtain the permission to interact with the element"}, "startTarget": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "startElement": {"type": "string", "description": "Human-readable source element description used to obtain the permission to interact with the element"}}, "additionalProperties": false}}, {"name": "browser_hover", "description": "Hover over element on page", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["target"], "properties": {"target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}}, {"name": "browser_select_option", "description": "Select an option in a dropdown", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["target", "values"], "properties": {"target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "values": {"type": "array", "items": {"type": "string"}, "description": "Array of values to select in the dropdown. This can be a single value or multiple values."}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}}, {"name": "browser_tabs", "description": "List, create, close, or select a browser tab.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["action"], "properties": {"url": {"type": "string", "description": "URL to navigate to in the new tab, used for new."}, "index": {"type": "number", "description": "Tab index, used for close/select. If omitted for close, current tab is closed."}, "action": {"enum": ["list", "new", "close", "select"], "type": "string", "description": "Operation to perform"}}, "additionalProperties": false}}, {"name": "browser_wait_for", "description": "Wait for text to appear or disappear or a specified time to pass", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"text": {"type": "string", "description": "The text to wait for"}, "time": {"type": "number", "description": "The time to wait in seconds, at most 30"}, "textGone": {"type": "string", "description": "The text to wait for to disappear"}}, "additionalProperties": false}}]', '{"at": "2026-10-04T12:26:47.471Z", "state": "connected", "toolCount": 25}', '2026-10-04 12:26:47.472481+00');
INSERT INTO public.connect_mcp_servers VALUES ('browser-agent_b3a45862-1825-469f-ac71-4f114c34432a', '{"id": "browser-agent_b3a45862-1825-469f-ac71-4f114c34432a", "bin": "cli.js", "pkg": "@playwright/mcp", "args": ["--browser", "chrome", "--executable-path", "C:\\Users\\Kunc GmbH\\AppData\\Local\\imput\\Helium\\Application\\chrome.exe", "--user-data-dir", "C:\\Users\\Kunc GmbH\\AppData\\Local\\ConnectAgents\\agent_b3a45862-1825-469f-ac71-4f114c34432a\\helium", "--output-dir", "C:\\Users\\Kunc GmbH\\AppData\\Local\\ConnectAgents\\agent_b3a45862-1825-469f-ac71-4f114c34432a\\output", "--image-responses", "omit", "--headless"], "title": "Mein Browser", "options": {"profile": "C:\\Users\\Kunc GmbH\\AppData\\Local\\ConnectAgents\\agent_b3a45862-1825-469f-ac71-4f114c34432a\\helium", "headless": true}, "secrets": [], "createdAt": "2026-10-04T13:43:28.891Z", "transport": "stdio", "catalogKey": "browser", "ownerAgentId": "agent_b3a45862-1825-469f-ac71-4f114c34432a"}', '[{"name": "browser_close", "description": "Close the page", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {}, "additionalProperties": false}}, {"name": "browser_resize", "description": "Resize the browser window", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["width", "height"], "properties": {"width": {"type": "number", "description": "Width of the browser window"}, "height": {"type": "number", "description": "Height of the browser window"}}, "additionalProperties": false}}, {"name": "browser_console_messages", "description": "Returns all console messages", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["level"], "properties": {"all": {"type": "boolean", "description": "Return all console messages since the beginning of the session, not just since the last navigation. Defaults to false."}, "level": {"enum": ["error", "warning", "info", "debug"], "type": "string", "default": "info", "description": "Level of the console messages to return. Each level includes the messages of more severe levels. Defaults to \"info\"."}, "filename": {"type": "string", "description": "File name to save the console messages to. Relative file names are resolved against the workspace root. If not provided, messages are returned as text."}}, "additionalProperties": false}}, {"name": "browser_handle_dialog", "description": "Handle a dialog", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["accept"], "properties": {"accept": {"type": "boolean", "description": "Whether to accept the dialog."}, "promptText": {"type": "string", "description": "The text of the prompt in case of a prompt dialog."}}, "additionalProperties": false}}, {"name": "browser_emulate_media", "description": "Emulate CSS media features for the page, for example switch between the light and dark color scheme. Omitted parameters are left unchanged; null clears an override.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"media": {"anyOf": [{"enum": ["screen", "print"], "type": "string"}, {"type": "null"}], "description": "Changes the CSS media type of the page"}, "contrast": {"anyOf": [{"enum": ["more", "no-preference"], "type": "string"}, {"type": "null"}], "description": "Emulates the prefers-contrast media feature"}, "colorScheme": {"anyOf": [{"enum": ["light", "dark"], "type": "string"}, {"type": "null"}], "description": "Emulates the prefers-color-scheme media feature"}, "forcedColors": {"anyOf": [{"enum": ["active", "none"], "type": "string"}, {"type": "null"}], "description": "Emulates the forced-colors media feature"}, "reducedMotion": {"anyOf": [{"enum": ["reduce", "no-preference"], "type": "string"}, {"type": "null"}], "description": "Emulates the prefers-reduced-motion media feature"}}, "additionalProperties": false}}, {"name": "browser_evaluate", "description": "Evaluate JavaScript expression on page or element", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["function"], "properties": {"target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}, "filename": {"type": "string", "description": "File name to save the result to. Relative file names are resolved against the workspace root. If not provided, result is returned as text."}, "function": {"type": "string", "description": "() => { /* code */ } or (element) => { /* code */ } when element is provided"}}, "additionalProperties": false}}, {"name": "browser_file_upload", "description": "Upload one or multiple files", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"paths": {"type": "array", "items": {"type": "string"}, "description": "The absolute paths to the files to upload. Can be single file or multiple files. If omitted, file chooser is cancelled."}}, "additionalProperties": false}}, {"name": "browser_drop", "description": "Drop files or MIME-typed data onto an element, as if dragged from outside the page. At least one of \"paths\" or \"data\" must be provided.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["target"], "properties": {"data": {"type": "object", "description": "Data to drop, as a map of MIME type to string value (e.g. {\"text/plain\": \"hello\", \"text/uri-list\": \"https://example.com\"}).", "propertyNames": {"type": "string"}, "additionalProperties": {"type": "string"}}, "paths": {"type": "array", "items": {"type": "string"}, "description": "Absolute paths to files to drop onto the element."}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}}, {"name": "browser_find", "description": "Search the accessibility snapshot of the current page for text or a regular expression. Returns matching snapshot nodes with a few lines of surrounding context (like search snippets), each shown under its path from the root of the tree, which is cheaper than capturing the whole snapshot when you only need to locate an element and its ref.", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "properties": {"text": {"type": "string", "description": "Plain text to search for in the page snapshot (case-insensitive substring match). Provide either text or regex, not both."}, "regex": {"type": "string", "description": "Regular expression to search for in the page snapshot. Matching is case-sensitive by default; wrap the pattern in slashes to add flags, e.g. \"/error/i\" for case-insensitive. Provide either text or regex, not both."}, "filename": {"type": "string", "description": "Save results to a file instead of returning them in the response. Relative file names are resolved against the workspace root."}}, "additionalProperties": false}}, {"name": "browser_fill_form", "description": "Fill multiple form fields", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["fields"], "properties": {"fields": {"type": "array", "items": {"type": "object", "required": ["target", "name", "type", "value"], "properties": {"name": {"type": "string", "description": "Human-readable field name"}, "type": {"enum": ["textbox", "checkbox", "radio", "combobox", "slider"], "type": "string", "description": "Type of the field"}, "value": {"type": "string", "description": "Value to fill in the field. If the field is a checkbox, the value should be `true` or `false`. If the field is a combobox, the value should be the text of the option."}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}, "description": "Fields to fill in"}}, "additionalProperties": false}}, {"name": "browser_press_key", "description": "Press a key on the keyboard", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["key"], "properties": {"key": {"type": "string", "description": "Name of the key to press or a character to generate, such as `ArrowLeft` or `a`"}}, "additionalProperties": false}}, {"name": "browser_type", "description": "Type text into editable element", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["target", "text"], "properties": {"text": {"type": "string", "description": "Text to type into the element"}, "slowly": {"type": "boolean", "description": "Whether to type one character at a time. Useful for triggering key handlers in the page. By default entire text is filled in at once."}, "submit": {"type": "boolean", "description": "Whether to submit entered text (press Enter after)"}, "target": {"type": "string", "description": "Exact target element reference from the page snapshot, or a unique element selector"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}}, {"name": "browser_navigate", "description": "Navigate to a URL", "inputSchema": {"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["url"], "properties": {"url": {"type": "string", "description": "The URL t